108	//! * exec result: array with keys 0..n, index, input, groups (+ indices when `d`;
109	//!   `indices.groups`); `groups` has a null prototype and is undefined without named groups.
110	//!   lastIndex: ToLength (−1 -> 0, 1.5 -> 1, NaN -> 0, Infinity -> fail); set to the match end
