196	/// Parses a flags string. `Err` is the SyntaxError message of the original runtime.
197	pub fn parse_flags(flags: &[u16]) -> Result<RegexFlags, String> {
198	    let mut f = RegexFlags::default();
199	    for ch in char::decode_utf16(flags.iter().copied()) {
200	        let ch = ch.unwrap_or('\u{FFFD}');
201	        let slot = match ch {
202	            'd' => &mut f.has_indices,
203	            'g' => &mut f.global,
204	            'i' => &mut f.ignore_case,
205	            'm' => &mut f.multiline,
206	            's' => &mut f.dot_all,
207	            'u' => &mut f.unicode,
208	            'v' => &mut f.unicode_sets,
209	            'y' => &mut f.sticky,
210	            _ => return Err(format!("invalid regular expression flag {}", ch)),
211	        };
212	        if *slot {
213	            return Err(format!("duplicate regular expression flag {}", ch));
214	        }
215	        *slot = true;
216	    }
217	    if f.unicode && f.unicode_sets {
218	        return Err("the u and v regular expression flags are mutually exclusive".into());
219	    }
220	    Ok(f)
221	}
