242	/// Compiles `pattern` (UTF-16) with `flags`. `Err` is the exact SyntaxError message.
243	pub fn compile(pattern: &[u16], flags: RegexFlags) -> Result<CompiledRegex, String> {
244	    // Parsing/compilation recurse on the pattern's nesting depth; deeply nested patterns
245	    // are compiled on a helper thread with a large stack so they cannot overflow ours.
246	    let (prog, names) = if nesting_depth(pattern) > 200 {
247	        let pat = pattern.to_vec();
248	        std::thread::scope(|s| {
249	            std::thread::Builder::new()
250	                .stack_size(1 << 30)
251	                .spawn_scoped(s, move || compile_program(&pat, flags))
252	                .map_err(|e| e.to_string())?
253	                .join()
254	                .unwrap_or_else(|_| Err("regular expression too large".to_string()))
255	        })?
256	    } else {
257	        compile_program(pattern, flags)?
258	    };
259	    Ok(CompiledRegex { inner: Rc::new(Inner { prog, flags, group_names: names, vm: RefCell::new(None) }) })
260	}
