262	type NamedGroups = Vec<(Vec<u16>, Vec<usize>)>;
263	
264	fn compile_program(pattern: &[u16], flags: RegexFlags) -> Result<(compiler::Program, NamedGroups), String> {
265	    let unicode = flags.unicode || flags.unicode_sets;
266	    let p = parser::Parser::new(pattern, flags.unicode, flags.unicode_sets, flags.ignore_case, flags.multiline, flags.dot_all);
267	    let ast = p.parse()?;
268	    let prog = compiler::Compiler::compile(&ast, unicode)?;
269	    // group names in source order, duplicates merged
270	    let mut names: NamedGroups = Vec::new();
271	    let mut index: std::collections::HashMap<&[u16], usize> = std::collections::HashMap::new();
272	    for (name, g) in &ast.group_names {
273	        match index.get(&name[..]) {
274	            Some(&k) => names[k].1.push(*g as usize),
275	            None => {
276	                index.insert(&name[..], names.len());
277	                names.push((name.clone(), vec![*g as usize]));
278	            }
279	        }
280	    }
281	    Ok((prog, names))
282	}
