284	/// Upper bound of the group / class nesting depth of a pattern.
285	fn nesting_depth(pattern: &[u16]) -> usize {
286	    let (mut d, mut max) = (0usize, 0usize);
287	    let mut i = 0;
288	    while i < pattern.len() {
289	        match pattern[i] {
290	            0x5C => i += 1,
291	            0x28 | 0x5B => {
292	                d += 1;
293	                max = max.max(d);
294	            }
295	            0x29 | 0x5D => d = d.saturating_sub(1),
296	            _ => {}
297	        }
298	        i += 1;
299	    }
300	    max
301	}
